/**
 * Build an Excel address/formula reference from a matched ODS reference.
 *
 * @param array{0: string, 1: ?string, 2: string, 3: ?string, 4: ?string, 5: ?string, 6: ?string, 7: ?string} $matches
 */
private static function convertReference(array $matches): string
{
    if ($matches[1] !== null) {
        $result = $matches[1] . '!' . $matches[2];
        if ($matches[3] !== null) {
            $result .= ':' . $matches[3];
        } elseif ($matches[4] !== null) {
            $result .= ':' . $matches[4];
        }

        return $result;
    }
    if ($matches[5] !== null) {
        return $matches[5] . ':' . $matches[6];
    }

    return $matches[7];
}

